import React from 'react';
import ReactDOM from 'react-dom/client';
import * as ReactDOMFull from 'react-dom';
import { jsx, jsxs, Fragment } from 'react/jsx-runtime';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import * as ReactQuery from '@tanstack/react-query';
import './index.css';
import { SellerCenterPage } from './components/SellerCenterPage';
import { api } from './api/client';
import './screens';
import type { InitialState } from './types';

// Shared React runtime for dynamically loaded module screen bundles
// (they treat react/react-dom as IIFE externals — see modules/Ecommerce/vite.config.ts).
{
  const w = window as unknown as Record<string, unknown>;
  w.React = React;
  w.ReactDOMClient = ReactDOM;
  w.ReactDOM = ReactDOMFull;
  w.ReactJSXRuntime = { jsx, jsxs, Fragment };
  w.ReactQuery = ReactQuery;
}

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5, // 5 minutes
      retry: 1,
    },
  },
});

const fallbackInitialState: InitialState = {
  user: { id: '1', name: 'Administrator', role: 'admin' },
  screens: [],
  menuSections: [],
  widgets: [],
  screenOptions: [],
  adminBar: { items: [] },
  page: { path: '/dashboard', title: 'Dashboard', screenId: 'overview' },
};

async function boot() {
  let initialState = fallbackInitialState;

  try {
    initialState = await api.getInitialState();
  } catch (err) {
    console.error('Failed to load initial state, using fallback', err);
  }

  const root = ReactDOM.createRoot(document.getElementById('root')!);
  root.render(
    <React.StrictMode>
      <QueryClientProvider client={queryClient}>
        <SellerCenterPage
          initialState={initialState}
          onBackToMain={() => {
            window.location.href = '/';
          }}
        />
      </QueryClientProvider>
    </React.StrictMode>,
  );
}

boot();